"""Admin quote states: once issued, the quote shows as sent to the client (read-only) with an Update quote action
that opens the editor, needs a reason, supersedes the old version and tells the client."""
import os
from playwright.sync_api import sync_playwright
HERE = os.path.dirname(os.path.abspath(__file__))
APP = 'file://' + os.path.join(HERE, '..', 'dist', 'listd-platform.html')
OUT = os.path.join(HERE, 'out', 'shots') + '/'; os.makedirs(OUT, exist_ok=True)
res = []; errs = []
def check(ok, m): res.append((ok, m)); print(('PASS ' if ok else 'FAIL ') + m, flush=True)
with sync_playwright() as pw:
    br = pw.chromium.launch(); p = br.new_page(viewport={'width': 1280, 'height': 900})
    p.on('pageerror', lambda e: errs.append(str(e)))
    W = lambda ms=300: p.wait_for_timeout(ms)
    def btn(t): p.locator('.a-main button:has-text("%s"), .a-modal button:has-text("%s")' % (t, t)).first.click(); W()
    def submit(): p.locator('.a-main form[data-form=wiz] button[type=submit]').click(); W()
    def role(r): p.click('[data-act=role][data-r=%s]' % r); W()
    def main(): return p.locator('.a-main').inner_text()
    def job(): return p.evaluate("() => { var j = Object.values(D.jobs)[0]; return [j.status, j.quotes.map(q => [q.v, q.status, q.totalP])]; }")
    p.goto(APP); W(600)
    p.click('[data-act=auth-mode][data-m=signup]'); W(); p.fill('#au-name', 'Ada Okafor'); p.fill('#au-email', 'ada@example.test'); p.fill('#au-password', 'Listd2026!'); p.fill('#au-confirm', 'Listd2026!'); p.check('input[name=terms]')
    p.click('form[data-form=auth-signup] button[type=submit]'); W(1500)
    p.click('label.a-opt:has(input[value=LANDLORD])'); p.check('input[name=authority]'); btn('Continue')
    p.fill('#ob-ph', '07700 900000'); btn('Save & continue'); p.fill('#ob-ba', '1 Test Road'); p.fill('#ob-bc', 'Bristol'); p.fill('#ob-bp', 'bs6 1aa'); btn('Save & continue')
    p.fill('#p-lbl', 'Redland Flat'); p.fill('#p-addr', '4 Redland Road, Bristol'); p.fill('#p-pc', 'bs6 6ab'); p.fill('#p-bed', '2'); p.select_option('#p-furn', 'unfurnished'); p.fill('#p-acode', 'Key safe 1234'); p.fill('#p-cn', 'Jo Tenant'); p.fill('#p-cp', '07700 900001'); btn('Save property'); btn('Finish setup')
    p.evaluate("go('new')"); W(); submit(); p.click('label.a-opt:has(input[value=CHECK_OUT])'); submit(); p.fill('#w-keys', '2 sets'); p.fill('#w-occ', 'Jo Tenant'); submit(); submit()
    p.fill('#w-date', p.evaluate("() => addWorkDays(isoDay(new Date()), 5)")); p.dispatch_event('#w-date', 'change'); W(); submit(); submit(); W(600)
    check(job() == ['QUOTED', [[1, 'ISSUED', 11000]]], 'rate-card quote issued to the client: ' + str(job()))
    role('admin'); p.fill('#au-name', 'Ops Admin'); p.fill('#au-email', 'ops@listd.test'); p.fill('#au-password', 'Admin2026!'); p.fill('#au-confirm', 'Admin2026!'); p.click('form[data-form=auth-admin-setup] button[type=submit]'); W(2000)
    p.evaluate("() => go('requests')"); W()
    check('Quote sent' in main(), 'admin request list shows "Quote sent"')
    p.evaluate("() => go('job', { id: Object.values(D.jobs)[0].id })"); W()
    t = main(); p.screenshot(path=OUT + 'qu1-sent.png', full_page=True)
    check('Quote v1 sent to client' in t and 'Waiting for the client' in t and p.locator('form[data-form=quote]').count() == 0, 'admin sees the sent state, not an open editor')
    check(p.locator('[data-act=q-edit]').count() == 1, 'Update quote button shown')
    btn('Update quote'); p.screenshot(path=OUT + 'qu2-edit.png', full_page=True)
    check(p.locator('form[data-form=quote]').count() == 1 and 'Update quote (v2)' in main() and p.locator('#q-why').count() == 1, 'Update quote opens the editor with a reason field')
    btn('Cancel'); check(p.locator('form[data-form=quote]').count() == 0 and 'sent to client' in main(), 'Cancel returns to the sent state without changes')
    btn('Update quote'); p.fill('input[name=l_u_0]', '120.00'); p.evaluate("() => { document.getElementById('q-why').required = false; document.querySelector('form[data-form=quote]').requestSubmit(); }"); W()
    check(job()[1] == [[1, 'ISSUED', 11000]], 'an update needs a reason')
    p.fill('#q-why', 'Larger garden confirmed on the call'); btn('Send updated quote to client')
    check(job() == ['QUOTED', [[1, 'SUPERSEDED', 11000], [2, 'ISSUED', 12000]]], 'v2 sent, v1 superseded: ' + str(job()))
    t = main(); check('Quote v2 sent to client' in t and 'Larger garden confirmed on the call' in t, 'sent state shows v2 and the reason')
    role('client'); p.evaluate("() => go('job', { id: Object.values(D.jobs)[0].id })"); W(); t = main()
    check('Your updated quote is ready: £120.00' in t and 'Larger garden confirmed on the call' in t, 'client is told the quote was updated and why')
    btn('Accept quote'); role('admin'); p.evaluate("() => go('job', { id: Object.values(D.jobs)[0].id })"); W()
    check('Accepted by the client' in main(), 'accepted quote waiting for payment shows as accepted')
    btn('Update quote'); p.fill('#q-why', 'Agreed discount'); p.fill('#q-disc', '10.00'); btn('Send updated quote to client')
    check(job() == ['QUOTED', [[1, 'SUPERSEDED', 11000], [2, 'SUPERSEDED', 12000], [3, 'ISSUED', 11000]]], 'updating an accepted quote sends a new version for the client to accept: ' + str(job()))
    role('client'); p.evaluate("() => go('job', { id: Object.values(D.jobs)[0].id })"); W(); btn('Accept quote'); p.locator('[data-act=pay]').first.click(); W()
    role('admin'); p.evaluate("() => go('job', { id: Object.values(D.jobs)[0].id })"); W()
    check(p.locator('[data-act=q-edit]').count() == 0, 'no Update quote once paid (extra work goes through a change order)')
    p.set_viewport_size({'width': 390, 'height': 800}); p.evaluate("() => { S.role='admin'; go('job', { id: Object.values(D.jobs)[0].id }); }"); W()
    check(p.evaluate("document.documentElement.scrollWidth") <= 392, 'fits a phone')
    br.close()
print('FAILS', [m for ok, m in res if not ok]); print('ERRORS', errs)
